changeSet.sql:
ALTER TABLE vaultnote.users ALTER COLUMN password_hash DROP NOT NULL;
CREATE TABLE vaultnote.oauth_identities ( id BIGINT GENERATED BY DEFAULT AS IDENTITY, user_id BIGINT NOT NULL, provider VARCHAR(32) NOT NULL, provider_subject VARCHAR(255) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT pk_oauth_identities PRIMARY KEY (id), CONSTRAINT uk_oauth_identities_provider_subject UNIQUE (provider, provider_subject), CONSTRAINT uk_oauth_identities_user_provider UNIQUE (user_id, provider), CONSTRAINT fk_oauth_identities_user FOREIGN KEY (user_id) REFERENCES vaultnote.users (id) ON DELETE CASCADE );
CREATE INDEX ix_oauth_identities_user_id ON vaultnote.oauth_identities (user_id);
